            case 11:
                return new Shape11[length];
            case 12:
                return new Shape12[length];
            case 13:
                return new Shape13[length];
            case 14:
                return new Shape14[length];
            case 15:
                return new Shape15[length];
            case 16:
                return new Shape16[length];
            default:
                throw new InvalidOperationException("no payload");
        }
